const path="/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/telematics/49.csv";
const data=await tools.Read({file_path:path});
if(typeof data!=="string") throw Error("Expected CSV text");
const lines=data.trimEnd().split("\n");
const rows=lines.slice(1).map((raw,i)=>{const [truck,at,lat,lon,engine,odo]=raw.split(",");return {raw,line:i+2,truck,at,lat:Number(lat),lon:Number(lon),engine,odo};});
text({source:"telematics/49.csv",truck21:rows.filter(r=>r.truck==="21").map(r=>({line:r.line,quote:r.raw}))});
const rad=x=>x*Math.PI/180;
const distance=r=>{const a=Math.sin(rad(r.lat-30.207)/2)**2+Math.cos(rad(30.207))*Math.cos(rad(r.lat))*Math.sin(rad(r.lon+97.756)/2)**2;return 6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));};
const window=rows.filter(r=>r.at>="2026-09-07T19:11:39Z"&&r.at<="2026-09-07T19:31:39Z");
text({source:"telematics/49.csv",window_row_count:window.length,within_3000m:window.filter(r=>distance(r)<3000).map(r=>({line:r.line,quote:r.raw})),nearest_window_rows:window.sort((a,b)=>distance(a)-distance(b)).slice(0,3).map(r=>({line:r.line,quote:r.raw}))});
